// historicalIntentDigest is the pre-change encoding, frozen from commit 8301cfd: the
// conversation, content, reply target and canonicalized attachment ids, hashed with the
// same length-prefixed fields the shipped version wrote. It is a deliberate copy, not a
// call into the production helper: fixtures for the compatibility tests must not be
// generated by the code whose behavior they check. The recorded-output test below pins
// the production helper itself against a digest emitted by the old release.
func historicalIntentDigest(conversationID, content string, attachmentIDs []string, replyToID string) string {
	hasher := sha256.New()
	field := func(value string) { fmt.Fprintf(hasher, "%d:%s", len(value), value) }
	field(conversationID)
	field(content)
	field(replyToID)
	field(strconv.Itoa(len(attachmentIDs)))
	attachments := append([]string(nil), attachmentIDs...)
	sort.Strings(attachments)
	for _, id := range attachments {
		field(id)
	}
	return hex.EncodeToString(hasher.Sum(nil))
}

// setReceiptDigest rewrites one stored receipt's intent to an encoding a prior version
// would have written, so the upgrade paths are exercised against real rows.
func setReceiptDigest(t *testing.T, s *Server, accountID, key, digest string) {
	t.Helper()
	result, err := s.store.Exec(`UPDATE message_operations SET intent_digest=? WHERE account_id=? AND idempotency_key=?`,
		digest, accountID, key)
	if err != nil {
		t.Fatal(err)
	}
	if rows, err := result.RowsAffected(); err != nil || rows != 1 {
		t.Fatalf("rewriting receipt %q touched %d rows (%v), want 1", key, rows, err)
	}
}

func storedReceiptDigest(t *testing.T, s *Server, accountID, key string) string {
	t.Helper()
	var digest string
	if err := s.store.QueryRow(`SELECT intent_digest FROM message_operations WHERE account_id=? AND idempotency_key=?`,
		accountID, key).Scan(&digest); err != nil {
		t.Fatal(err)
	}
	return digest
}

// threadReplies counts the messages filed into a thread, excluding its root: the root is
// a promoted channel message, so counting every row with the thread id would say one more
// than the replies that were actually sent there.
func threadReplies(t *testing.T, s *Server, threadID, rootID string) int {
	t.Helper()
	var count int
	if err := s.store.QueryRow(`SELECT count(*) FROM messages WHERE thread_id=? AND id<>?`, threadID, rootID).Scan(&count); err != nil {
		t.Fatal(err)
	}
	return count
}

// channelPosts counts a channel's own messages, excluding everything filed into a thread.
func channelPosts(t *testing.T, s *Server, channelID string) int {
	t.Helper()
	var count int
	if err := s.store.QueryRow(`SELECT count(*) FROM messages WHERE channel_id=? AND thread_id IS NULL`, channelID).Scan(&count); err != nil {
		t.Fatal(err)
	}
	return count
}

func receiptRefused(t *testing.T, w *httptest.ResponseRecorder, what string) {
	t.Helper()
	if w.Code != http.StatusConflict {
		t.Fatalf("%s answered %d %s, want a conflict", what, w.Code, w.Body.String())
	}
	if !strings.Contains(w.Body.String(), "different message") {
		t.Fatalf("%s did not answer as a destination conflict: %s", what, w.Body.String())
	}
}

func receiptTerminal(t *testing.T, w *httptest.ResponseRecorder, what string) {
	t.Helper()
	if w.Code != http.StatusConflict {
		t.Fatalf("%s answered %d %s, want a terminal conflict", what, w.Code, w.Body.String())
	}
	body := w.Body.String()
	if !strings.Contains(body, "gone") && !strings.Contains(body, "expired") {
		t.Fatalf("%s did not answer with a documented terminal outcome: %s", what, body)
	}
}

// The pre-thread canonical encoding is pinned, byte for byte, because it is the format
// durable receipts already contain. Rewriting it — even "tidying" the field order —
// silently turns every stored retry into a conflict, which is exactly how the thread
// identity change broke unchanged ordinary retries (review 15, V15-02). The digest below
// is sha256 over the length-prefixed fields the pre-change code wrote: conversation
// "conv", content "text", reply "reply", attachment count "0".
func TestTheLegacyDigestEncodingIsTheRecordedOne(t *testing.T) {
	const recorded = "994dd742203f052397d9adde6ec0f41c7f78a8c1ae6deba48e694b2f056e9540"
	if got := legacySendIntentDigest("conv", "text", nil, "reply"); got != recorded {
		t.Fatalf("legacySendIntentDigest = %s, want the recorded %s", got, recorded)
	}
	// The frozen copy is the same encoding, so the behavioral fixtures below describe the
	// format the old release actually wrote.
	if historicalIntentDigest("conv", "text", nil, "reply") != recorded {
		t.Fatal("the frozen pre-change encoding disagrees with the recorded digest")
	}
	// It canonicalizes attachment order exactly as the recorded encoding did, and it
	// still binds the destination.
	if legacySendIntentDigest("conv", "text", []string{"second", "first"}, "reply") !=
		legacySendIntentDigest("conv", "text", []string{"first", "second"}, "reply") {
		t.Fatal("the pre-change encoding stopped canonicalizing attachment order")
	}
	if legacySendIntentDigest("conv", "text", nil, "reply") == legacySendIntentDigest("other", "text", nil, "reply") {
		t.Fatal("the pre-change encoding does not bind its conversation")
	}
	// A pre-thread digest can never be the current encoding of an ordinary send: the
	// current format writes the thread field between the conversation and the content.
	if legacySendIntentDigest("conv", "text", nil, "reply") == sendIntentDigest("conv", "", "text", nil, "reply") {
		t.Fatal("the legacy encoding is indistinguishable from the current one")
	}
}

// An unchanged ordinary retry against a receipt written before thread identity was
// added must still replay as the operation it was. The same receipt must not answer
// changed text — and must never answer a thread send, because it does not describe
// that destination and no pre-change receipt can have recorded one.
func TestAnUpgradedReceiptStillAnswersItsUnchangedOrdinaryRetry(t *testing.T) {
	s, handler := testServer(t)
	admin := setupAdmin(t, s, handler)
	channelID := textChannelID(t, s)

	created := request(t, handler, "POST", "/api/channels/"+channelID+"/messages",
		messageInput{Content: "an ordinary line", IdempotencyKey: "upgrade-legacy-1"}, admin)
	if created.Code != http.StatusCreated {
		t.Fatalf("original send: %d %s", created.Code, created.Body.String())
	}
	message := readJSON[db.Message](t, created)

	// The receipt as the upgrade leaves it: the digest the pre-thread version wrote.
	legacy := historicalIntentDigest(channelID, "an ordinary line", nil, "")
	setReceiptDigest(t, s, sessionUserID(t, s, admin), "upgrade-legacy-1", legacy)

	replay := request(t, handler, "POST", "/api/channels/"+channelID+"/messages",
		messageInput{Content: "an ordinary line", IdempotencyKey: "upgrade-legacy-1"}, admin)
	if replay.Code != http.StatusOK {
		t.Fatalf("an unchanged retry against a pre-change receipt answered %d: %s", replay.Code, replay.Body.String())
	}
	if again := readJSON[db.Message](t, replay); again.ID != message.ID {
		t.Fatalf("the pre-change receipt returned %s, want %s", again.ID, message.ID)
	}
	if count := messagesIn(t, s, channelID); count != 1 {
		t.Fatalf("the replay left %d messages, want 1", count)
	}

	// Changed work under the same key is still a conflict, not the old message.
	changed := request(t, handler, "POST", "/api/channels/"+channelID+"/messages",
		messageInput{Content: "a different line", IdempotencyKey: "upgrade-legacy-1"}, admin)
	if changed.Code != http.StatusConflict {
		t.Fatalf("changed text under the old key answered %d: %s", changed.Code, changed.Body.String())
	}

	// The same key as a thread send is the same conflict: the receipt describes a
	// channel message, and answering with it would hand a thread send someone else's
	// destination.
	thread := startThread(t, handler, channelID, admin, message.ID, "upgrade thread", "")
	threaded := request(t, handler, "POST", "/api/threads/"+thread.ID+"/messages",
		messageInput{Content: "an ordinary line", IdempotencyKey: "upgrade-legacy-1"}, admin)
	if threaded.Code != http.StatusConflict {
		t.Fatalf("a thread send under the old key answered %d: %s", threaded.Code, threaded.Body.String())
	}
	if count := messagesIn(t, s, channelID); count != 1 {
		t.Fatalf("the conflicts left %d messages, want the original one", count)
	}

	// The permitted control: the same thread with a new key sends, so the refusal
	// above was about the receipt and not about the thread.
	fresh := request(t, handler, "POST", "/api/threads/"+thread.ID+"/messages",
		messageInput{Content: "an ordinary line", IdempotencyKey: "upgrade-legacy-2"}, admin)
	if fresh.Code != http.StatusCreated {
		t.Fatalf("a new key in the thread answered %d: %s", fresh.Code, fresh.Body.String())
	}
}

// A thread send's receipt remembers its thread as part of the destination: the same
// key replays through the thread, and cannot be replayed through the channel it lives
// in, where it would be different work.
func TestAThreadReceiptKeepsItsThread(t *testing.T) {
	s, handler := testServer(t)
	channelID, alice, _, _ := threadFixture(t, s, handler)
	messages := readJSON[[]db.Message](t, request(t, handler, "GET", "/api/channels/"+channelID+"/messages", nil, alice))
	root := messages[0]
	thread := startThread(t, handler, channelID, alice, root.ID, "receipt thread", "")

	first := request(t, handler, "POST", "/api/threads/"+thread.ID+"/messages",
		messageInput{Content: "a threaded line", IdempotencyKey: "thread-receipt-1"}, alice)
	if first.Code != http.StatusCreated {
		t.Fatalf("thread send: %d %s", first.Code, first.Body.String())
	}
	sent := readJSON[db.Message](t, first)

	replay := request(t, handler, "POST", "/api/threads/"+thread.ID+"/messages",
		messageInput{Content: "a threaded line", IdempotencyKey: "thread-receipt-1"}, alice)
	if replay.Code != http.StatusOK {
		t.Fatalf("an unchanged thread retry answered %d: %s", replay.Code, replay.Body.String())
	}
	if again := readJSON[db.Message](t, replay); again.ID != sent.ID || again.ThreadID != thread.ID {
		t.Fatalf("the thread replay returned %+v, want %s in %s", again, sent.ID, thread.ID)
	}

	moved := request(t, handler, "POST", "/api/channels/"+channelID+"/messages",
		messageInput{Content: "a threaded line", IdempotencyKey: "thread-receipt-1"}, alice)
	if moved.Code != http.StatusConflict {
		t.Fatalf("the thread receipt answered a channel send: %d %s", moved.Code, moved.Body.String())
	}
	// The root is part of the thread, so one reply means two rows: the root plus the
	// reply that the conflict above did not create twice.
	var stored int
	if err := s.store.QueryRow(`SELECT count(*) FROM messages WHERE thread_id=? AND id<>?`, thread.ID, root.ID).Scan(&stored); err != nil {
		t.Fatal(err)
	}
	if stored != 1 {
		t.Fatalf("the thread holds %d replies, want 1", stored)
	}
}

// A receipt written while named threads already existed, but before the thread joined
// the intent digest, hashes the parent conversation and the words and says nothing about
// the thread. It must still resolve an unchanged retry through the thread it was sent to
// — and must not become an ordinary channel replay, or a replay into a sibling thread.
func TestAPreThreadThreadReceiptReplaysOnlyThroughItsThread(t *testing.T) {
	s, handler := testServer(t)
	channelID, alice, _, _ := threadFixture(t, s, handler)
	roots := readJSON[[]db.Message](t, request(t, handler, "GET", "/api/channels/"+channelID+"/messages", nil, alice))
	thread := startThread(t, handler, channelID, alice, roots[0].ID, "the original thread", "")

	sent := request(t, handler, "POST", "/api/threads/"+thread.ID+"/messages",
		messageInput{Content: "the same words", IdempotencyKey: "prethread-thread-1"}, alice)
	if sent.Code != http.StatusCreated {
		t.Fatalf("thread send: %d %s", sent.Code, sent.Body.String())
	}
	message := readJSON[db.Message](t, sent)

	// Rewrite the receipt to the encoding the release before thread-in-digest wrote.
	account := sessionUserID(t, s, alice)
	legacy := historicalIntentDigest(channelID, "the same words", nil, "")
	setReceiptDigest(t, s, account, "prethread-thread-1", legacy)
	if storedReceiptDigest(t, s, account, "prethread-thread-1") == sendIntentDigest(channelID, thread.ID, "the same words", nil, "") {
		t.Fatal("the fixture did not actually predate the thread-in-digest encoding")
	}

	// The unchanged retry resolves through its original thread, to the original message.
	replay := request(t, handler, "POST", "/api/threads/"+thread.ID+"/messages",
		messageInput{Content: "the same words", IdempotencyKey: "prethread-thread-1"}, alice)
	if replay.Code != http.StatusOK {
		t.Fatalf("an unchanged pre-thread thread retry answered %d: %s", replay.Code, replay.Body.String())
	}
	if again := readJSON[db.Message](t, replay); again.ID != message.ID || again.ThreadID != thread.ID {
		t.Fatalf("the pre-thread thread replay returned %+v, want %s in %s", again, message.ID, thread.ID)
	}
	replies := threadReplies(t, s, thread.ID, thread.RootMessageID)
	if replies != 1 {
		t.Fatalf("the replay left %d thread replies, want 1", replies)
	}

	// The parent channel is not that destination: the retry is refused and writes nothing.
	posts := channelPosts(t, s, channelID)
	channelReplay := request(t, handler, "POST", "/api/channels/"+channelID+"/messages",
		messageInput{Content: "the same words", IdempotencyKey: "prethread-thread-1"}, alice)
	receiptRefused(t, channelReplay, "a pre-thread thread receipt replayed at the parent channel")
	if got := channelPosts(t, s, channelID); got != posts {
		t.Fatalf("the parent-channel refusal wrote %d messages", got-posts)
	}

	// A sibling thread is not that destination either.
	sibling := startThread(t, handler, channelID, alice, roots[1].ID, "a sibling thread", "")
	siblingReplay := request(t, handler, "POST", "/api/threads/"+sibling.ID+"/messages",
		messageInput{Content: "the same words", IdempotencyKey: "prethread-thread-1"}, alice)
	receiptRefused(t, siblingReplay, "a pre-thread thread receipt replayed in a sibling thread")
	if got := threadReplies(t, s, sibling.ID, sibling.RootMessageID); got != 0 {
		t.Fatalf("the sibling-thread refusal wrote %d replies", got)
	}

	// The permitted control: the same thread with a new key sends, so the refusals were
	// about the receipt and not about the destination.
	fresh := request(t, handler, "POST", "/api/threads/"+thread.ID+"/messages",
		messageInput{Content: "the same words", IdempotencyKey: "prethread-thread-2"}, alice)
	if fresh.Code != http.StatusCreated {
		t.Fatalf("a new key in the original thread answered %d: %s", fresh.Code, fresh.Body.String())
	}
}

// The other half of the same history: a pre-thread receipt for an ordinary channel
// message replays in the channel and nowhere else, and the same-key retry in a thread
// conflicts instead of becoming a thread reply.
func TestAPreThreadOrdinaryReceiptReplaysOnlyInTheChannel(t *testing.T) {
	s, handler := testServer(t)
	admin := setupAdmin(t, s, handler)
	channelID := textChannelID(t, s)
	account := sessionUserID(t, s, admin)

	created := request(t, handler, "POST", "/api/channels/"+channelID+"/messages",
		messageInput{Content: "an ordinary pre-thread line", IdempotencyKey: "prethread-ordinary-1"}, admin)
	if created.Code != http.StatusCreated {
		t.Fatalf("send: %d %s", created.Code, created.Body.String())
	}
	message := readJSON[db.Message](t, created)
	setReceiptDigest(t, s, account, "prethread-ordinary-1",
		historicalIntentDigest(channelID, "an ordinary pre-thread line", nil, ""))

	// A thread in the same channel, started from a different message.
	root := request(t, handler, "POST", "/api/channels/"+channelID+"/messages",
		messageInput{Content: "a root for the thread", IdempotencyKey: "prethread-root-1"}, admin)
	if root.Code != http.StatusCreated {
		t.Fatalf("root send: %d %s", root.Code, root.Body.String())
	}
	thread := startThread(t, handler, channelID, admin, readJSON[db.Message](t, root).ID, "an unrelated thread", "")

	posts, replies := channelPosts(t, s, channelID), threadReplies(t, s, thread.ID, thread.RootMessageID)
	threadReplay := request(t, handler, "POST", "/api/threads/"+thread.ID+"/messages",
		messageInput{Content: "an ordinary pre-thread line", IdempotencyKey: "prethread-ordinary-1"}, admin)
	receiptRefused(t, threadReplay, "an ordinary pre-thread receipt replayed in a thread")
	if got := threadReplies(t, s, thread.ID, thread.RootMessageID); got != replies {
		t.Fatalf("the thread refusal wrote %d replies", got-replies)
	}
	if got := channelPosts(t, s, channelID); got != posts {
		t.Fatalf("the thread refusal wrote %d channel messages", got-posts)
	}

	// Its own channel replays the original message.
	channelReplay := request(t, handler, "POST", "/api/channels/"+channelID+"/messages",
		messageInput{Content: "an ordinary pre-thread line", IdempotencyKey: "prethread-ordinary-1"}, admin)
	if channelReplay.Code != http.StatusOK {
		t.Fatalf("an unchanged channel retry answered %d: %s", channelReplay.Code, channelReplay.Body.String())
	}
	if again := readJSON[db.Message](t, channelReplay); again.ID != message.ID {
		t.Fatalf("the channel replay returned %s, want %s", again.ID, message.ID)
	}

	// Changed work under the old key is still a conflict.
	changed := request(t, handler, "POST", "/api/channels/"+channelID+"/messages",
		messageInput{Content: "different words entirely", IdempotencyKey: "prethread-ordinary-1"}, admin)
	receiptRefused(t, changed, "changed text under a pre-thread receipt")

	// Another conversation is the same conflict, even with identical words.
	other := readJSON[db.Channel](t, request(t, handler, "POST", "/api/channels",
		db.Channel{Name: "prethread other", Type: "text", MaxVoiceUsers: 8, Visibility: "public"}, admin))
	moved := request(t, handler, "POST", "/api/channels/"+other.ID+"/messages",
		messageInput{Content: "an ordinary pre-thread line", IdempotencyKey: "prethread-ordinary-1"}, admin)
	receiptRefused(t, moved, "a pre-thread receipt replayed in another conversation")
	if count := messagesIn(t, s, other.ID); count != 0 {
		t.Fatalf("the conversation refusal wrote %d messages", count)
	}
}

// Attachment order is not part of the intent: the pre-change encoding canonicalized it,
// so a retry that names the same files in another order still replays, and the replay
// claims nothing twice.
func TestAPreThreadReceiptCanonicalizesItsAttachments(t *testing.T) {
	s, handler := testServer(t)
	admin := setupAdmin(t, s, handler)
	channelID := textChannelID(t, s)
	account := sessionUserID(t, s, admin)

	first := readJSON[db.Attachment](t, directUpload(t, handler, admin, channelID))
	second := readJSON[db.Attachment](t, directUpload(t, handler, admin, channelID))
	created := request(t, handler, "POST", "/api/channels/"+channelID+"/messages",
		messageInput{Content: "with files", IdempotencyKey: "prethread-files-1",
			AttachmentIDs: []string{first.ID, second.ID}}, admin)
	if created.Code != http.StatusCreated {
		t.Fatalf("attachment send: %d %s", created.Code, created.Body.String())
	}
	message := readJSON[db.Message](t, created)
	setReceiptDigest(t, s, account, "prethread-files-1",
		historicalIntentDigest(channelID, "with files", []string{first.ID, second.ID}, ""))

	replay := request(t, handler, "POST", "/api/channels/"+channelID+"/messages",
		messageInput{Content: "with files", IdempotencyKey: "prethread-files-1",
			AttachmentIDs: []string{second.ID, first.ID}}, admin)
	if replay.Code != http.StatusOK {
		t.Fatalf("a reordered-attachment retry answered %d: %s", replay.Code, replay.Body.String())
	}
	if again := readJSON[db.Message](t, replay); again.ID != message.ID {
		t.Fatalf("the reordered replay returned %s, want %s", again.ID, message.ID)
	}
	if count := messagesIn(t, s, channelID); count != 1 {
		t.Fatalf("the reordered replay left %d messages, want 1", count)
	}
	if claimed := attachmentClaimedMessage(t, s, first.ID); claimed != message.ID {
		t.Fatalf("the replay moved the first file into %q", claimed)
	}
}

// A backfilled receipt has no digest at all: the migration records the destination and
// the message, never the intent. It still binds where the operation was sent — the
// surviving message says so — so a retry in a thread of the same channel is refused
// while the channel replay returns the recorded message.
func TestABackfilledReceiptBindsItsDestination(t *testing.T) {
	s, handler := testServer(t)
	admin := setupAdmin(t, s, handler)
	channelID := textChannelID(t, s)
	account := sessionUserID(t, s, admin)

	created := request(t, handler, "POST", "/api/channels/"+channelID+"/messages",
		messageInput{Content: "backfilled words", IdempotencyKey: "backfill-1"}, admin)
	if created.Code != http.StatusCreated {
		t.Fatalf("send: %d %s", created.Code, created.Body.String())
	}
	message := readJSON[db.Message](t, created)
	setReceiptDigest(t, s, account, "backfill-1", "")

	root := request(t, handler, "POST", "/api/channels/"+channelID+"/messages",
		messageInput{Content: "backfill thread root", IdempotencyKey: "backfill-root-1"}, admin)
	thread := startThread(t, handler, channelID, admin, readJSON[db.Message](t, root).ID, "backfill thread", "")

	posts, replies := channelPosts(t, s, channelID), threadReplies(t, s, thread.ID, thread.RootMessageID)
	threadReplay := request(t, handler, "POST", "/api/threads/"+thread.ID+"/messages",
		messageInput{Content: "backfilled words", IdempotencyKey: "backfill-1"}, admin)
	receiptRefused(t, threadReplay, "a backfilled receipt replayed in a thread")
	if got := threadReplies(t, s, thread.ID, thread.RootMessageID); got != replies {
		t.Fatalf("the thread refusal wrote %d replies", got-replies)
	}
	if got := channelPosts(t, s, channelID); got != posts {
		t.Fatalf("the thread refusal wrote %d channel messages", got-posts)
	}

	channelReplay := request(t, handler, "POST", "/api/channels/"+channelID+"/messages",
		messageInput{Content: "backfilled words", IdempotencyKey: "backfill-1"}, admin)
	if channelReplay.Code != http.StatusOK {
		t.Fatalf("the channel replay answered %d: %s", channelReplay.Code, channelReplay.Body.String())
	}
	if again := readJSON[db.Message](t, channelReplay); again.ID != message.ID {
		t.Fatalf("the backfilled channel replay returned %s, want %s", again.ID, message.ID)
	}
	// A backfilled receipt recorded no intent, so different words under the same key are
	// answered from the recorded message rather than reproduced as new work.
	changed := request(t, handler, "POST", "/api/channels/"+channelID+"/messages",
		messageInput{Content: "different words under a backfilled key", IdempotencyKey: "backfill-1"}, admin)
	if changed.Code != http.StatusOK {
		t.Fatalf("changed text under a backfilled key answered %d: %s", changed.Code, changed.Body.String())
	}
	if again := readJSON[db.Message](t, changed); again.ID != message.ID {
		t.Fatalf("changed text under a backfilled key returned %s, want the recorded %s", again.ID, message.ID)
	}
	if count := messagesIn(t, s, channelID); count != 2 {
		t.Fatalf("the backfilled replays left %d messages, want the message and its thread root", count)
	}
}

// A thread's root is an ordinary channel message that was promoted later. Its receipt —
// legacy or backfilled — describes a channel send, and the channel retry must keep
// resolving to it even though the message's current thread_id names the thread. The
// thread itself is still refused: promotion is not a destination change.
func TestAPromotedRootKeepsItsOriginalChannelDestination(t *testing.T) {
	for _, test := range []struct {
		name      string
		key       string
		content   string
		overwrite func(t *testing.T, s *Server, account, key, content, channelID string)
	}{
		{
			name: "legacy digest", key: "promoted-legacy-1", content: "a root promoted later",
			overwrite: func(t *testing.T, s *Server, account, key, content, channelID string) {
				setReceiptDigest(t, s, account, key, historicalIntentDigest(channelID, content, nil, ""))
			},
		},
		{
			name: "backfilled digest", key: "promoted-blank-1", content: "a root promoted later",
			overwrite: func(t *testing.T, s *Server, account, key, _, _ string) {
				setReceiptDigest(t, s, account, key, "")
			},
		},
	} {
		t.Run(test.name, func(t *testing.T) {
			s, handler := testServer(t)
			admin := setupAdmin(t, s, handler)
			channelID := textChannelID(t, s)
			account := sessionUserID(t, s, admin)

			created := request(t, handler, "POST", "/api/channels/"+channelID+"/messages",
				messageInput{Content: test.content, IdempotencyKey: test.key}, admin)
			if created.Code != http.StatusCreated {
				t.Fatalf("send: %d %s", created.Code, created.Body.String())
			}
			message := readJSON[db.Message](t, created)
			test.overwrite(t, s, account, test.key, test.content, channelID)

			thread := startThread(t, handler, channelID, admin, message.ID, "promoted root", "")
			var root string
			if err := s.store.QueryRow(`SELECT COALESCE(root_message_id,'') FROM threads WHERE id=?`, thread.ID).Scan(&root); err != nil {
				t.Fatal(err)
			}
			if root != message.ID {
				t.Fatalf("the thread's root is %q, want the promoted %q", root, message.ID)
			}
			var placement string
			if err := s.store.QueryRow(`SELECT COALESCE(thread_id,'') FROM messages WHERE id=?`, message.ID).Scan(&placement); err != nil {
				t.Fatal(err)
			}
			if placement != thread.ID {
				t.Fatalf("the promoted root is filed into %q, want %q", placement, thread.ID)
			}

			// The thread is not where the operation was sent: same key there is refused.
			replies := threadReplies(t, s, thread.ID, message.ID)
			threadReplay := request(t, handler, "POST", "/api/threads/"+thread.ID+"/messages",
				messageInput{Content: test.content, IdempotencyKey: test.key}, admin)
			receiptRefused(t, threadReplay, "a promoted root replayed in its own thread")
			if got := threadReplies(t, s, thread.ID, message.ID); got != replies {
				t.Fatalf("the thread refusal wrote %d replies", got-replies)
			}

			// The channel is: the original operation still resolves to its message.
			channelReplay := request(t, handler, "POST", "/api/channels/"+channelID+"/messages",
				messageInput{Content: test.content, IdempotencyKey: test.key}, admin)
			if channelReplay.Code != http.StatusOK {
				t.Fatalf("the original channel retry answered %d: %s", channelReplay.Code, channelReplay.Body.String())
			}
			if again := readJSON[db.Message](t, channelReplay); again.ID != message.ID {
				t.Fatalf("the promoted root's channel retry returned %s, want %s", again.ID, message.ID)
			}
		})
	}
}

// When the recorded message is gone, the destination cannot be established from the
// surviving result. The answer stays the documented terminal outcome — expired, or
// committed and gone — at both endpoints, and nothing is recreated or rerouted.
func TestAnErasedPreThreadReceiptStaysTerminalWithoutADestinationGuess(t *testing.T) {
	s, handler := testServer(t)
	channelID, alice, _, _ := threadFixture(t, s, handler)
	roots := readJSON[[]db.Message](t, request(t, handler, "GET", "/api/channels/"+channelID+"/messages", nil, alice))
	thread := startThread(t, handler, channelID, alice, roots[0].ID, "erased receipt thread", "")
	account := sessionUserID(t, s, alice)

	sent := request(t, handler, "POST", "/api/threads/"+thread.ID+"/messages",
		messageInput{Content: "vanished words", IdempotencyKey: "erased-thread-1"}, alice)
	if sent.Code != http.StatusCreated {
		t.Fatalf("thread send: %d %s", sent.Code, sent.Body.String())
	}
	message := readJSON[db.Message](t, sent)
	// A pre-thread receipt for a thread send, as the prior release left it.
	setReceiptDigest(t, s, account, "erased-thread-1",
		historicalIntentDigest(channelID, "vanished words", nil, ""))
	if w := request(t, handler, "DELETE", "/api/messages/"+message.ID,
		map[string]string{"confirm": message.ID}, alice); w.Code != http.StatusOK {
		t.Fatalf("delete: %d %s", w.Code, w.Body.String())
	}

	posts, replies := channelPosts(t, s, channelID), threadReplies(t, s, thread.ID, thread.RootMessageID)
	threadReplay := request(t, handler, "POST", "/api/threads/"+thread.ID+"/messages",
		messageInput{Content: "vanished words", IdempotencyKey: "erased-thread-1"}, alice)
	receiptTerminal(t, threadReplay, "an erased pre-thread thread receipt")
	channelReplay := request(t, handler, "POST", "/api/channels/"+channelID+"/messages",
		messageInput{Content: "vanished words", IdempotencyKey: "erased-thread-1"}, alice)
	receiptTerminal(t, channelReplay, "an erased pre-thread receipt at the channel")
	if got := threadReplies(t, s, thread.ID, thread.RootMessageID); got != replies {
		t.Fatalf("the erased receipt recreated %d thread replies", got-replies)
	}
	if got := channelPosts(t, s, channelID); got != posts {
		t.Fatalf("the erased receipt recreated %d channel messages", got-posts)
	}
	var remaining int
	if err := s.store.QueryRow(`SELECT count(*) FROM messages WHERE id=?`, message.ID).Scan(&remaining); err != nil {
		t.Fatal(err)
	}
	if remaining != 0 {
		t.Fatalf("the erased receipt resurrected message %s", message.ID)
	}
}

// Expiry is preserved for pre-thread receipts, including at the thread endpoint that used
// to refuse them for the wrong reason: once the window has closed and the content is gone,
// the answer says so and the key stays claimed instead of becoming new work.
func TestAnExpiredPreThreadReceiptIsNeverNewWork(t *testing.T) {
	s, handler := testServer(t)
	channelID, alice, _, _ := threadFixture(t, s, handler)
	roots := readJSON[[]db.Message](t, request(t, handler, "GET", "/api/channels/"+channelID+"/messages", nil, alice))
	thread := startThread(t, handler, channelID, alice, roots[0].ID, "expired receipt thread", "")
	account := sessionUserID(t, s, alice)

	sent := request(t, handler, "POST", "/api/threads/"+thread.ID+"/messages",
		messageInput{Content: "an old threaded line", IdempotencyKey: "expired-thread-1"}, alice)
	if sent.Code != http.StatusCreated {
		t.Fatalf("thread send: %d %s", sent.Code, sent.Body.String())
	}
	message := readJSON[db.Message](t, sent)
	setReceiptDigest(t, s, account, "expired-thread-1",
		historicalIntentDigest(channelID, "an old threaded line", nil, ""))
	if w := request(t, handler, "DELETE", "/api/messages/"+message.ID,
		map[string]string{"confirm": message.ID}, alice); w.Code != http.StatusOK {
		t.Fatalf("delete: %d %s", w.Code, w.Body.String())
	}
	old := db.Timestamp(time.Now().Add(-48 * time.Hour))
	if _, err := s.store.Exec(`UPDATE message_operations SET created_at=?,expires_at=? WHERE account_id=? AND idempotency_key=?`,
		old, old, account, "expired-thread-1"); err != nil {
		t.Fatal(err)
	}

	replies := threadReplies(t, s, thread.ID, thread.RootMessageID)
	threadReplay := request(t, handler, "POST", "/api/threads/"+thread.ID+"/messages",
		messageInput{Content: "an old threaded line", IdempotencyKey: "expired-thread-1"}, alice)
	if threadReplay.Code != http.StatusConflict || !strings.Contains(threadReplay.Body.String(), "expired") {
		t.Fatalf("the expired thread retry answered %d: %s", threadReplay.Code, threadReplay.Body.String())
	}
	channelReplay := request(t, handler, "POST", "/api/channels/"+channelID+"/messages",
		messageInput{Content: "an old threaded line", IdempotencyKey: "expired-thread-1"}, alice)
	if channelReplay.Code != http.StatusConflict || !strings.Contains(channelReplay.Body.String(), "expired") {
		t.Fatalf("the expired channel retry answered %d: %s", channelReplay.Code, channelReplay.Body.String())
	}
	if got := threadReplies(t, s, thread.ID, thread.RootMessageID); got != replies {
		t.Fatalf("the expired retry recreated %d thread replies", got-replies)
	}
	// The key is not released: an explicit new send with a new key is the only way on.
	if w := request(t, handler, "POST", "/api/threads/"+thread.ID+"/messages",
		messageInput{Content: "an old threaded line", IdempotencyKey: "expired-thread-2"}, alice); w.Code != http.StatusCreated {
		t.Fatalf("the explicit new send was refused: %d %s", w.Code, w.Body.String())
	}
}
